def poly(xs: list, x: float) -> float:
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[2] * x^2 + ... + xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])

def find_zero(xs: list) -> float:
    """
    xs are coefficients of a polynomial, in descending powers of x.
    find_zero finds x such that poly(x) = 0.
    find_zero returns only one zero point, even if there are multiple.
    find_zero only takes a list xs having an even number of coefficients
    and ensures the largest non-zero coefficient is non-trivial (i.e., not zero).
    """
    if len(xs) % 2 != 0 or max(xs, key=abs) == 0:
        raise ValueError("xs must have an even number of coefficients and at least one non-zero coefficient.")

    # Newton's method for finding roots
    def newton(guess, xs, tol=1e-6, max_iter=100):
        for _ in range(max_iter):
            p = poly(xs, guess)
            if abs(p) < tol:
                return round(guess, 2)
            dp = sum([i * coeff * math.pow(guess, i-1) for i, coeff in enumerate(xs)])
            guess -= p / dp
        return round(guess, 2)

    return newton(0, xs)

