def find_zero(xs: list) -> float:
    """
    xs are coefficients of a polynomial.
    find_zero finds x such that poly(x) = 0.
    find_zero returns only one zero point, even if there are many.
    Moreover, find_zero only takes a list xs having an even number of coefficients
    and with the largest non-zero coefficient as the leading coefficient.
    """
    assert len(xs) % 2 == 0, "xs must have an even number of coefficients."
    assert max(abs(c) for c in xs) == abs(xs[0]), "The largest non-zero coefficient must be the leading one."

    # Separate the polynomial into two halves
    half_len = len(xs) // 2
    left_half = xs[:half_len]
    right_half = xs[half_len:]

    # Use Newton's method for root finding, assuming the root lies in [-10, 10]
    def newton_method(f, df, x0, tol=1e-6, max_iter=100):
        x = x0
        for _ in range(max_iter):
            fx = f(x)
            if abs(fx) < tol:
                return x
            dfx = df(x)
            if dfx == 0:
                break
            x = x - fx / dfx
        raise ValueError("Newton's method did not converge.")

    # Define f(x) = poly(x)
    def f(x):
        return poly(xs, x)

    # Define f'(x), the derivative of the polynomial
    def df(x):
        return sum(i * coeff * math.pow(x, i - 1) for i, coeff in enumerate(xs) if i != 0)

    # Initial guess: -5 (in the range [-10, 10])
    try:
        return newton_method(f, df, -5)
    except ValueError:
        raise ValueError("No real root found in the given range.")

def sort_third(l: list):
    """This function takes a list l and returns a list l' such that
    l' is identical to l in the indicies that are not divisible by three, while its values at the indicies that are divisible by three are equal
    to the values of the corresponding indicies of l, but sorted.
    """
    third_indices = [i for i in range(len(l)) if (i+1) % 3 == 0] # find indices divisible by 3
    sorted_third = sorted(l[i] for i in third_indices) # sort values at those indices
    return [sorted_third.pop(0) if (i+1) % 3 == 0 else l[i] for i in range(len(l))] # replace original values with sorted ones

