def pairs_sum_to_zero(l):
    # Initialize an empty set to track seen elements
    seen = set()

    # Iterate through the list
    for num in l:
        # If the number is 0, check if any previously seen number sums to zero
        if num == 0:
            if 0 in seen:
                return True
            seen.add(num)

        # If the number is non-zero, check if there's a pair in the set that sums to zero
        else:
            for prev_seen in seen:
                if num + prev_seen == 0:
                    return True
            seen.add(num)

    # If no pair is found that sums to zero, return False
    return False

def median(l: list):
    """Return median of elements in the list l."""
    sorted_l = sorted(l)
    n = len(sorted_l)
    if n % 2 == 0:
        return (sorted_l[n // 2 - 1] + sorted_l[n // 2]) / 2
    else:
        return sorted_l[n // 2]

