    num_digits = len(str(x))

    # Handle shift greater than number of digits
    if shift > num_digits:
        # Reverse the digits
        return int(str(x)[::-1])

    # Shift the digits right
    result = int(str(x)[-shift:] + str(x)[:-shift])

    return str(result)

def circular_shift(x, shift):
    """Circular shift the digits of the integer x, shift the digits right by shift
    and return the result as a string.
    If shift > number of digits, return digits reversed.
    """
    x_str = str(x)
    shift = shift % len(x_str)  # Handle cases where shift is larger than len(x_str)

    if shift == 0:
        return x_str
    elif shift > 0:
        return x_str[-shift:] + x_str[:-shift]
    else:
        return x_str[:shift][::-1] + x_str[:shift][::-1]

