def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # right, down, left, up
    visited = [[False for _ in range(N)] for _ in range(N)]
    min_heap = [(grid[0][0], 0, 0, [grid[0][0]])]  # (value, row, col, path)

    while min_heap:
        val, row, col, path = heappop(min_heap)
        if len(path) == k:
            return path

        if (row, col) not in visited:
            visited[row][col] = True

            for dr, dc in directions:
                new_row, new_col = row + dr, col + dc
                if 0 <= new_row < N and 0 <= new_col < N and not visited[new_row][new_col]:
                    heappush(min_heap, (grid[new_row][new_col], new_row, new_col, path + [grid[new_row][new_col]]))

    return []  # No path of length k was found

