def minPath(grid, k):
    n = len(grid)
    min_path = float('inf')
    best_path = []

    # Generate a dictionary mapping cell values to their (row, col) positions
    cell_pos = {val: (i, j) for i, row in enumerate(grid) for j, val in enumerate(row)}

    # Define movement directions (up, down, left, right)
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    # Function to check if a move is within the grid boundaries
    def is_valid_move(r, c):
        return 0 <= r < n and 0 <= c < n

    # BFS function to find paths of length k
    def bfs(start_val, k):
        nonlocal min_path, best_path
        queue = deque([(start_val, cell_pos[start_val], [start_val])])
        visited = set([cell_pos[start_val]])

        while queue:
            curr_val, (r, c), path = queue.popleft()

            # If path length equals k, check if it's smaller than the current minimum
            if len(path) == k:
                if sum(path) < min_path:
                    min_path = sum(path)
                    best_path = path
                    return
            else:
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if is_valid_move(nr, nc) and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        new_path = path + [grid[nr][nc]]
                        queue.append((grid[nr][nc], (nr, nc), new_path))

    # Try each cell as the starting point
    for val in grid[0]:
        bfs(val, k)

    return best_path

