def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    min_path = float('inf')
    result_path = []

    def in_bounds(r, c):
        return 0 <= r < N and 0 <= c < N

    def neighbors(r, c):
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if in_bounds(nr, nc):
                yield (nr, nc)

    # Priority queue to store (current_sum, current_path, current_position)
    pq = [(grid[0][0], [grid[0][0]], (0, 0))]  # Start at top-left corner

    while pq:
        curr_sum, curr_path, (curr_r, curr_c) = heappop(pq)
        if len(curr_path) == k:
            if curr_sum < min_path:
                min_path = curr_sum
                result_path = curr_path
            continue

        for nr, nc in neighbors(curr_r, curr_c):
            new_path = curr_path + [grid[nr][nc]]
            heappush(pq, (curr_sum + grid[nr][nc], new_path, (nr, nc)))

    return result_path

