    if not arr or len(arr) == 0:
        raise ValueError("Input array must be sorted and non-empty.")
    # Calculate the length of the array
    length = len(arr)
    # Check if the length is less than n/2
    if length < n // 2:
        return target in arr
    # Count occurrences of the target
    count = arr.count(target)
    # Determine if the count is greater than n/2
    return count > (n // 2)

def is_majority(arr, n, x):
    # Check if the array length is even to determine n/2
    if len(arr) % 2 == 1:
        n_half = len(arr) // 2 + 1
    else:
        n_half = len(arr) // 2

    # Count occurrences of x in the array
    count_x = arr.count(x)

    # Determine if x is the majority element
    if count_x > n_half:
        return True
    elif count_x == n_half:
        return False
    else:
        return False

