def max_sum_increasing_subseq(nums, n, i, k):
    """
    Finds the maximum sum of increasing subsequence from the prefix until ith index, including the kth element after i.

    Parameters:
    nums (list): The list of integers.
    n (int): The length of the list.
    i (int): The index up to which the subsequence should be considered from the start.
    k (int): The number of elements after index i to include in the subsequence.

    Returns:
    int: Maximum sum of the increasing subsequence.
    """

    if i >= n or k <= 0:
        return 0

    # Initial sums from the start till i
    dp = [0] * (i + 1)
    dp[0] = nums[0]

    for j in range(1, i + 1):
        dp[j] = nums[j]
        for prev_j in range(j):
            if nums[j] > nums[prev_j] and dp[j] < dp[prev_j] + nums[j]:
                dp[j] = dp[prev_j] + nums[j]

    # Consider the elements after i up to the kth one
    for l in range(i + 1, min(i + k, n)):
        # Maintain the prefix subset using binary search
        dp[l] = nums[l]
        for prev_l in range(l):
            if nums[l] > nums[prev_l] and dp[l] < dp[prev_l] + nums[l]:
                dp[l] = dp[prev_l] + nums[l]

    return max(dp)

