from typing import List

def max_product(nums: List[int]) -> int:
    """
    This function finds the maximum product of numbers in an increasing subsequence of the given array.

    Args:
    nums (List[int]): Input array of integers.

    Returns:
    int: Maximum product of an increasing subsequence.
    """
    if not nums:
        return 0

    n = len(nums)
    left_products = [1] * n
    right_products = [1] * n
    max_product = nums[0]

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                left_products[i] = max(left_products[i], nums[i] * left_products[j])
        max_product = max(max_product, left_products[i])

    for i in range(n-2, -1, -1):
        for j in range(n-1, i, -1):
            if nums[i] < nums[j]:
                right_products[i] = max(right_products[i], nums[i] * right_products[j])
        max_product = max(max_product, right_products[i])

    return max_product

