def max_product(arr):
    if not arr:
        return 0

    n = len(arr)
    max_product = arr[0]
    max_length = 1
    max_ending_here = arr[0]

    for i in range(1, n):
        if arr[i] > max_ending_here:
            max_ending_here = arr[i]
            max_length += 1
        else:
            if max_ending_here * arr[i] > max_product:
                max_product = max_ending_here * arr[i]
            max_ending_here = arr[i]
            max_length = 1

    if max_ending_here * max_product > max_product:
        max_product = max_ending_here * max_product

    return max_product

def tuple_intersection(list1, list2):
    """
    Find the intersection of tuples in two lists, considering tuples equal irrespective of order.

    Args:
    list1: List of tuples.
    list2: List of tuples.

    Returns:
    A set of tuples that appear in both lists ignoring order within the tuples.
    """
    # Normalize tuples by sorting their elements
    normalized1 = {tuple(sorted(t)) for t in list1}
    normalized2 = {tuple(sorted(t)) for t in list2}

    # Find intersection of normalized tuples
    intersect = normalized1.intersection(normalized2)

    # Return the intersecting tuples in the original order as they appeared first in list1
    # This is to match the expected output format (without sorted tuples, just original ones)
    # Create a lookup from normalized tuple to original tuple in list1 (first occurrence)
    lookup = {}
    for t in list1:
        key = tuple(sorted(t))
        if key not in lookup:
            lookup[key] = t

    return {lookup[t] for t in intersect}

def tuple_intersection(list1, list2):
    # Normalize tuples by sorting their elements so order doesn't matter
    set1 = {tuple(sorted(t)) for t in list1}
    set2 = {tuple(sorted(t)) for t in list2}
    # Find intersection
    return set1.intersection(set2)

def tuple_intersection(list1, list2):
    """
    Returns a set of tuples that appear in both list1 and list2,
    considering tuples with the same elements in any order as equal.
    """
    def normalize(t):
        return tuple(sorted(t))

    set1 = {normalize(t) for t in list1}
    set2 = {normalize(t) for t in list2}

    intersection = set1 & set2

    # Return in tuple form as in input, sorted so (3,4) not (4,3)
    return intersection

def tuple_intersection(tuples1, tuples2):
    # Convert the tuple lists to sets of frozensets to handle unordered tuples
    set1 = {frozenset(t) for t in tuples1}
    set2 = {frozenset(t) for t in tuples2}
    # Find the intersection of sets
    intersection = set1.intersection(set2)
    # Convert back to a set of tuples
    return {tuple(sorted(t)) for t in intersection}

