def sort_counter(counter):
    """
    Function to sort a dictionary by value.

    :param counter: Dictionary with string keys and integer values.
    :return: A list of tuples, where each tuple contains a key-value pair from the input dictionary sorted by value in descending order.
    """
    # Using sorted() function along with lambda to sort dict items by value
    return sorted(counter.items(), key=lambda item: item[1], reverse=True)

