def get_ludic(n):
    """
    Get all lucid numbers smaller than or equal to a given integer.
    A lucid number is a member of the sequence defined by the following rule:
    Each subsequent term in the sequence is the next available integer that is coprime to all previous terms.
    """
    ludic = []
    primes = [True for _ in range(n+1)]

    # Sieve of Eratosthenes to find primes up to n
    p = 2
    while p*p <= n:
        if primes[p]:
            for i in range(p*p, n+1, p):
                primes[i] = False
        p += 1

    # Generating lucid sequence
    for i in range(1, n+1):
        if primes[i]:
            ludic.append(i)
            for j in ludic[:-1]:
                if i % j == 0:
                    break
            else:
                continue
            ludic.append(i)

    return ludic

def get_ludic(n):
    """
    Returns a list of lucid numbers smaller than or equal to the given integer `n`.
    A lucid number is a number that is not divisible by any of the smaller numbers (excluding itself) within its range.

    :param n: upper limit for lucid numbers
    :return: list of lucid numbers up to `n`
    """
    def is_lucid(num):
        """
        Checks if a number is lucid within its range.
        """
        if num < 2:
            return True
        for i in range(1, num):
            if num % i == 0:
                return False
        return True

    ludic_numbers = []
    for i in range(1, n + 1):
        if is_lucid(i):
            ludic_numbers.append(i)
    return ludic_numbers

