def move_zero(lst):
    # Initialize an empty list to store non-zero elements
    non_zero_elements = []

    # Iterate through the input list
    for element in lst:
        # If the element is zero, append it to a separate list
        if element == 0:
            non_zero_elements.append(0)
        else:
            # Otherwise, append the non-zero element to the non_zero_elements list
