    curr_index = 0
    for i in range(len(arr)):
        if arr[i] != 0:
            arr[curr_index] = arr[i]
            curr_index += 1
    # Fill the remainder of the array with zeroes
    while curr_index < len(arr):
        arr[curr_index] = 0
        curr_index += 1
    return arr

